// Per-action skilling data for the XP calculator — every row is one repeatable
// action (a log chopped, a lap run, a potion mixed) with the XP it gives, so the
// calculator can say exactly how many of them reach a target.
//
// GENERATED — sourced from the 07.gg skill calculators (https://07.gg/calculators/skill/agility
// and siblings), retrieved 2026-10-07, then cleaned up:
// - fractional XP/hour rates rounded to whole numbers
// - prayer fish offerings' nameless inputs filled in with the fish's own name
// - rows sorted by level, then name
//
// 07.gg has no Farming or Sailing calculator, so those skills have no entries.
// Combat skills are left out on purpose: their XP comes from whatever you're
// fighting, not from a repeatable action.

export interface ActionItem {
  name: string;
  quantity: number;
}

export interface SkillAction {
  name: string;
  /** Minimum level to perform the action. */
  level: number;
  /** XP granted per single action. */
  xp: number;
  /** Members-only; free-to-play when absent. */
  members?: boolean;
  /** OSRS item id for the row icon — see `itemIconUrl`. */
  icon?: number;
  /** Game sprite id for the row icon, used when there's no item (spells) — see `spriteIconUrl`. */
  sprite?: number;
  /** Approximate XP/hour, where 07.gg gives one. */
  xpPerHour?: number;
  /** Items one action consumes. */
  inputs?: ActionItem[];
  /** Items one action produces. */
  outputs?: ActionItem[];
}

